import React, { useState, useEffect } from 'react';
import { db, auth } from '../firebase';
import { getDoc, doc, updateDoc, collection, getDocs, increment, addDoc, onSnapshot } from 'firebase/firestore';

const defaultStoreItems = [
  { name: "🏅 바둑 칭호 선택권", description: "닉네임 옆에 다음과 같은 희귀 칭호를 선택해서 사용\n초고수, 명인 (名人), 대가 (大家), 국수 (國手), 신의 한 수, 입신, 바둑 마스터, 대마 불사, 반상을 지배하는자, 불멸의 전략가", cost: 2000 },
  { name: "💎 닉네임 컬러 변경", description: "닉네임 색상을 커스텀 가능 (한 달 지속)", cost: 600 }, // 새로운 상품 추가
];

const Store = () => {
  const [items, setItems] = useState([]);
  const [userMileage, setUserMileage] = useState(0);
  const [selectedTitle, setSelectedTitle] = useState(null); // 선택한 칭호 상태
  const [nicknameColor, setNicknameColor] = useState(null); // 선택한 닉네임 컬러
  const [isNicknameColorPurchased, setIsNicknameColorPurchased] = useState(false); // 닉네임 컬러 구매 여부
  const [isTitlePurchased, setIsTitlePurchased] = useState(false); // 칭호 구매 여부
  const [message, setMessage] = useState(""); // 칭호 선택 후 메시지
  const user = auth.currentUser;

  useEffect(() => {
    if (!user) return;

    const userRef = doc(db, 'users', user.uid);
    const unsubscribe = onSnapshot(userRef, (snapshot) => {
      if (snapshot.exists()) {
        setUserMileage(snapshot.data().mileage || 0);
        setSelectedTitle(snapshot.data().title); // 칭호 업데이트
        setNicknameColor(snapshot.data().nicknameColor); // 닉네임 컬러 업데이트
      }
    });

    const fetchStoreItems = async () => {
      const storeRef = collection(db, "store");
      const querySnapshot = await getDocs(storeRef);

      if (querySnapshot.empty) {
        await Promise.all(
          defaultStoreItems.map(async (item) => {
            const storeSnapshot = await getDocs(storeRef);
            if (storeSnapshot.docs.length >= 10) return;

            const existingItemsQuery = await getDocs(storeRef);
            const existingItems = existingItemsQuery.docs.map(doc => doc.data().name);

            if (!existingItems.includes(item.name)) {
              await addDoc(storeRef, item);
            }
          })
        );

        const newSnapshot = await getDocs(storeRef);
        const newItems = newSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setItems(newItems);
      } else {
        const fetchedItems = querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        setItems(fetchedItems);
      }
    };

    fetchStoreItems();
    return () => unsubscribe();
  }, [user]);

  const handlePurchase = async (itemId, cost, itemName) => {
    if (!user) return;
    if (userMileage < cost) return alert('마일리지가 부족합니다.');

    const userRef = doc(db, 'users', user.uid);
    await updateDoc(userRef, { mileage: increment(-cost) });

    const purchasesRef = collection(db, 'purchases');
    await addDoc(purchasesRef, {
      userId: user.uid,
      itemName,
      cost,
      timestamp: new Date(),
    });

    if (itemName === "💎 닉네임 컬러 변경") {
      setIsNicknameColorPurchased(true); // 닉네임 컬러 변경 구매 상태 업데이트
    }

    if (itemName === "🏅 바둑 칭호 선택권") {
      setIsTitlePurchased(true); // 칭호 선택권 구매 상태 업데이트
    }

    alert(`"${itemName}"을(를) 성공적으로 구매했습니다!`);
  };

  const handleNicknameColorChange = async (color) => {
    if (!user) return;
    const userRef = doc(db, 'users', user.uid);

    // 닉네임 컬러 변경 (users 컬렉션의 nameColor 필드에 저장)
    await updateDoc(userRef, { nameColor: color });

    setNicknameColor(color); // 닉네임 컬러 상태 업데이트
    setMessage(`닉네임 색상을 ${color}으로 변경하셨습니다!`); // 색상 변경 메시지
  };

  const handleTitleSelect = async (title) => {
    if (!user) return;
    const userRef = doc(db, 'users', user.uid);

    // 칭호 변경 (users 컬렉션의 title 필드에 저장)
    await updateDoc(userRef, { title: title });

    setSelectedTitle(title); // 칭호 상태 업데이트
    setMessage(`칭호를 ${title}으로 변경하셨습니다!`); // 칭호 변경 메시지
  };

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-2xl font-bold mb-4">마일리지 상점</h1>
      <p className="mb-4">보유 마일리지: <span className="font-semibold">{userMileage}점</span></p>

      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
        {items.length > 0 ? (
          items.map((item) => (
            <div key={item.id} className="p-4 border rounded-lg shadow-md">
              <h2 className="text-xl font-semibold">{item.name}</h2>
              <p className="text-gray-700">{item.description}</p>
              <button
                onClick={() => handlePurchase(item.id, item.cost, item.name)}
                className={`mt-2 px-4 py-2 rounded-lg ${userMileage >= item.cost ? 'bg-blue-500 text-white' : 'bg-gray-400 text-gray-700 cursor-not-allowed'}`}
                disabled={userMileage < item.cost}
              >
                구매 ({item.cost} 마일리지)
              </button>
            </div>
          ))
        ) : (
          <p>상점에 아이템이 없습니다. 잠시 후 다시 시도해주세요.</p>
        )}
      </div>

      {/* 칭호 선택 프래그먼트 */}
      {isTitlePurchased && !isNicknameColorPurchased && (
        <div className="mt-6 p-4 border rounded-lg shadow-md bg-gray-100">
          <h2 className="text-xl font-semibold mb-2">칭호 선택</h2>
          <p className="mb-4">다음 칭호 중에서 선택해주세요:</p>
          <div className="grid grid-cols-2 gap-4">
            {["초고수", "명인", "대가", "국수", "신의 한 수", "입신", "바둑 마스터", "대마 불사"].map((title) => (
              <button
                key={title}
                onClick={() => handleTitleSelect(title)}
                className="px-4 py-2 text-white rounded-lg bg-blue-500"
              >
                {title}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* 닉네임 컬러 변경 프래그먼트 */}
      {isNicknameColorPurchased && (
        <div className="mt-6 p-4 border rounded-lg shadow-md bg-gray-100">
          <h2 className="text-xl font-semibold mb-2">컬러 선택</h2>
          <p className="mb-4">구매하실 컬러를 선택하세요:</p>
          <div className="grid grid-cols-3 gap-4">
            {["red", "blue", "purple", "green", "orange", "navy", "gold"].map((color) => (
              <button
                key={color}
                onClick={() => handleNicknameColorChange(color)}
                className="px-4 py-2 text-white rounded-lg"
                style={{ backgroundColor: color }}
              >
                {color}
              </button>
            ))}
          </div>
        </div>
      )}

      {nicknameColor && (
        <div className="mt-6 p-4 border rounded-lg shadow-md bg-gray-100">
          <h2 className="text-xl font-semibold mb-2">닉네임 색상</h2>
          <p className="mb-4">현재 닉네임 색상: <span style={{ color: nicknameColor }}>{nicknameColor}</span></p>
        </div>
      )}

      {message && (
        <div className="mt-4 text-green-500 font-semibold">
          {message}
        </div>
      )}

      {selectedTitle && (
        <div className="mt-4">
          <p>프로필 닉네임: <span className="font-semibold">{selectedTitle} {user.displayName}</span></p>
        </div>
      )}
    </div>
  );
};

export default Store;
