import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import Login from "../pages/Login";
import { doc, getDoc, collection, query, where, getDocs } from "firebase/firestore";
import { db } from "../firebase"; // Firebase 초기화 파일
import defaultProfileImage from "../images/바통이.jpg"; // 기본 이미지 경로

const Article = ({ user, handleLogout }) => {
  const [userData, setUserData] = useState(null);

  // matchApplications에서 playerName이 일치하는 사용자의 스태미나 가져오기
  const fetchStaminaFromMatchApplications = async (userUid) => {
    const q = query(
      collection(db, "matchApplications"),
      where("userId", "==", userUid)
    );

    try {
      const querySnapshot = await getDocs(q);
      if (!querySnapshot.empty) {
        const matchData = querySnapshot.docs[0].data();
        return matchData.stamina ?? 0;  // stamina가 없으면 기본값 0 반환
      } else {
        console.log("해당 이름을 가진 매치 신청서 데이터가 없습니다.");
        return 0;
      }
    } catch (err) {
      console.error("matchApplications에서 기력 값을 가져오는 데 실패했습니다.", err);
      return 0;
    }
  };

  useEffect(() => {
    if (user) {
      const fetchUserData = async () => {
        const userDocRef = doc(db, "users", user.uid);
        try {
          const docSnap = await getDoc(userDocRef);
          if (docSnap.exists()) {
            const userData = docSnap.data();

            // 먼저 사용자 데이터를 설정 (stamina 제외)
            setUserData(userData);

            // 사용자 이름을 기반으로 matchApplications에서 stamina 가져오기
            const staminaFromMatchApp = await fetchStaminaFromMatchApplications(user.uid);

            // 기존 데이터에 stamina 업데이트
            setUserData((prevData) => ({
              ...prevData,
              stamina: staminaFromMatchApp
            }));

            console.log("User Data:", { ...userData, stamina: staminaFromMatchApp });
          }
        } catch (err) {
          console.error("사용자 데이터 불러오기 실패:", err);
        }
      };

      fetchUserData();
    }
  }, [user]);

  useEffect(() => {
    if (userData) {
      console.log("사용자 기력 값:", userData.stamina);
    }
  }, [userData]);

  // 랭크 계산 함수
  const getRank = (rating) => {
    if (rating >= 1576) {
      if (rankIndex >= 1 && rankIndex <= 1) {
        return { rank: "챌린저", className: "rank-challenger" };  
      } else if (rankIndex >= 2 && rankIndex <= 4) {
        return { rank: "그랜드 마스터", className: "rank-grandmaster" };  
      } else if (rankIndex >= 5 && rankIndex <= 10) {
        return { rank: "마스터", className: "rank-master" };  
      } else {
        return { rank: "다이아", className: "rank-diamond" };  
      }
    }
    
    if (rating >= 1551) {
      return { rank: "플래티넘", className: "rank-platinum" };
    } else if (rating >= 1526) {
      return { rank: "골드", className: "rank-gold" };
    } else if (rating >= 1501) {
      return { rank: "실버", className: "rank-silver" };
    } else {
      return { rank: "브론즈", className: "rank-bronze" };
    }
  };
  const rankIndex = userData ? userData.rankIndex || 0 : 0;

  // 스태미나 급수 계산 함수
  const getStaminaRank = (stamina) => {
    if (stamina === undefined || stamina === null || isNaN(stamina)) {
      return "정보 없음";
    }

    if (stamina >= 1000) {
      return `${Math.floor((stamina - 1000) / 100) + 1}단`;
    } else {
      return `${18 - Math.floor(stamina / 50)}급`;
    }
  };

  return (
    <article className="article bg-white p-4 rounded-lg shadow-md">
      {!user ? (
        <div className="login-container">
          <h2 className="text-xl font-bold mb-2">로그인</h2>
          <Login />
        </div>
      ) : (
        <div className="logout-container">
          <h2 className="text-xl font-bold mb-2">프로필</h2>
          {userData ? (
            <div className="user-info">
              <img
                src={userData.profilePicture || defaultProfileImage} // 프로필 사진이 없으면 기본 이미지 사용
                alt="프로필"
                className="rounded-full mb-4"
                style={{ width: '100px', height: '100px' }}
              />
              <p><strong>이름:</strong> <span
                  style={{
                    color: userData.nameColor || "black", // nameColor가 없으면 기본값으로 black
                  }}
                >{userData.chosenTitle ? `${userData.chosenTitle} ${userData.name}` : userData.name}</span></p> {/* 칭호를 이름 앞에 붙임 */}
              <p><strong>랭크:</strong> <span className={getRank(userData.rating).className}>{getRank(userData.rating).rank}</span></p>
              <p><strong>기력:</strong> {getStaminaRank(userData.stamina)}</p>
              <p><strong>마일리지:</strong> {userData.mileage}점</p>
              <div className="mt-2">
                <Link to="/mypage" className="text-blue-500 underline">
                  마이페이지
                </Link>
              </div>
            </div>
          ) : (
            <p>로딩 중...</p>
          )}
          {/* 로그아웃 버튼은 항상 표시 */}
        <button
          onClick={handleLogout}
          className="mt-3 bg-red-500 text-white px-4 py-2 rounded-md"
        >
          로그아웃
        </button>
        </div>
      )}
    </article>
  );
};

export default Article; 
