import React, { useEffect, useState, useRef } from "react";

const BadukBoard = () => {
  const [turn, setTurn] = useState("B"); // B = Black, W = White
  const [boardState, setBoardState] = useState(
    Array(19).fill(null).map(() => Array(19).fill(null))
  ); // 19x19 보드 상태 추적용
  const boardRef = useRef(null); // WGo.Board 객체를 useRef로 저장

  useEffect(() => {
    if (boardRef.current) {
    boardRef.current.turn = turn === "B" ? window.WGo.B : window.WGo.W;
    console.log(`WGo 보드 턴 업데이트: ${turn}`);
  }
    console.log("useEffect 실행");

    const scriptExists = document.querySelector('script[src*="wgo.min.js"]');
    console.log("scriptExists:", scriptExists);

    if (!scriptExists) {
      const script = document.createElement("script");
      script.src = `${process.env.PUBLIC_URL}/wgo.js-master/wgo/wgo.min.js`;
      script.async = true;

      script.onload = () => {
        console.log("wgo.min.js 로드 완료");
        if (window.WGo) {
          initializeBoard();
        } else {
          console.error("WGo 객체가 제대로 로드되지 않았습니다.");
        }
      };

      script.onerror = (error) => {
        console.error("wgo.min.js 파일 로드 실패:", error);
      };

      document.body.appendChild(script);

      return () => {
        document.body.removeChild(script);
      };
    } else {
      console.log("이미 스크립트 로드됨");
      initializeBoard(); // 이미 스크립트가 로드된 경우 보드 생성
    }
  }, []);

  // 바둑판 초기화 함수
  const initializeBoard = () => {
    const boardElement = document.getElementById("board");
    console.log("initializeBoard 실행, boardElement:", boardElement);

    if (!boardElement) return;

    const newBoard = new window.WGo.Board(boardElement, {
      width: 500,
    });

    boardRef.current = newBoard; // useRef에 저장
    newBoard.turn = window.WGo.B; // 흑돌 시작

    newBoard.addEventListener("click", (x, y) => {
      console.log(`Board clicked at: (${x}, ${y})`);
      handleBoardClick(x, y, newBoard);
    });
  };

  // 자유도 계산 함수
  const countLiberties = (board, x, y, color, visited) => {
    console.log(`countLiberties 실행 - x: ${x}, y: ${y}, color: ${color}`);
    if (x < 0 || x >= 19 || y < 0 || y >= 19) return 0;
    if (visited[x][y]) return 0;
    visited[x][y] = true;

    if (board[x][y] === null) return 1; // 빈 자리는 자유도 추가
    if (board[x][y] !== color) return 0; // 다른 색의 돌은 연결되지 않음

    console.log(`countLiberties - continuing search for liberties at: (${x}, ${y})`);

    // 같은 색의 돌을 이어서 연결된 부분을 계속해서 탐색
    return (
      countLiberties(board, x + 1, y, color, visited) +
      countLiberties(board, x - 1, y, color, visited) +
      countLiberties(board, x, y + 1, color, visited) +
      countLiberties(board, x, y - 1, color, visited)
    );
  };

  // 자살 금지 및 포위된 돌 제거
  const checkForSuicideAndRemoveCaptured = (board, x, y, color) => {
    console.log(`checkForSuicideAndRemoveCaptured 실행 - ${board}x: ${x}, y: ${y}, color: ${color}`);
    const visited = Array(19).fill(null).map(() => Array(19).fill(false));
    const liberties = countLiberties(board, x, y, color, visited);

    console.log(`Liberties of the stone at (${x}, ${y}): ${liberties}`);

    if (liberties === 0) {
      alert("자살 착수는 불가능합니다!");
      return false;
    }

    // 상대 돌이 포위되었으면 제거
    const opponentColor = color === "B" ? "W" : "B";
    const newBoardState = board.map((row) => [...row]);

    const removeCapturedStones = (board, opponentColor) => {
      console.log(`removeCapturedStones 실행 - opponentColor: ${opponentColor}`);
      const captured = [];
      for (let i = 0; i < 19; i++) {
        for (let j = 0; j < 19; j++) {
          if (board[i][j] === opponentColor && !captured.some(([x, y]) => x === i && y === j)) {
            console.log(`Captured stone found at (${i}, ${j})`);
            const group = [];
            findCapturedStones(board, i, j, opponentColor, group);
            const liberties = countLiberties(board, i, j, opponentColor, Array(19).fill(null).map(() => Array(19).fill(false)));
            console.log(`Captured group at (${i}, ${j}) has ${liberties} liberties`);

            if (liberties === 0) {
              captured.push(...group);
            }
          }
        }
      }

      captured.forEach(([x, y]) => {
        console.log(`Removing captured stone at (${x}, ${y})`);
        newBoardState[x][y] = null;
        boardRef.current?.clear(x, y); // WGo에서 해당 좌표의 돌을 제거
      });

      return newBoardState;
    };

    const findCapturedStones = (board, x, y, color, group) => {
      console.log(`findCapturedStones 실행 - x: ${x}, y: ${y}, color: ${color}`);
      if (x < 0 || x >= 19 || y < 0 || y >= 19) return;
      if (board[x][y] !== color) return;

      group.push([x, y]);
      board[x][y] = null; // 돌을 제거하기 위한 처리

      findCapturedStones(board, x + 1, y, color, group);
      findCapturedStones(board, x - 1, y, color, group);
      findCapturedStones(board, x, y + 1, color, group);
      findCapturedStones(board, x, y - 1, color, group);
    };

    const updatedBoard = removeCapturedStones(newBoardState, opponentColor);
    setBoardState(updatedBoard);
    return true;
  };

  // 바둑판 클릭 핸들러
  const handleBoardClick = (x, y, newBoard) => {
    console.log(`handleBoardClick 실행 - x: ${x}, y: ${y}`);
    if (!newBoard) {
      console.error("보드가 초기화되지 않았습니다.");
      return;
    }

    if (boardState[x][y]) {
      alert("이미 돌이 놓여있습니다.");
      return;
    }

    // 착수
    const newBoardState = [...boardState];
    newBoardState[x][y] = turn;
    console.log({turn});
    const opponentCaptured = checkForSuicideAndRemoveCaptured(newBoardState, x, y, turn);

    if (!opponentCaptured) return;

    // 착수 후 돌 추가
    newBoard.addObject({
      x: x,
      y: y,
      c: newBoard.turn,
    });

    setBoardState(newBoardState);
    console.log({turn});
    // 턴 변경
    setTurn((prevTurn) => {
      const newTurn = prevTurn === "B" ? "W" : "B";
      console.log(`새로운 턴: ${newTurn}`);  // 이제 setTurn 후에 로그가 찍히게 됩니다.
      return newTurn;
    });
    console.log({turn});
    // 새로운 턴을 반영
    newBoard.turn = newBoard.turn === window.WGo.B ? window.WGo.W : window.WGo.B;
  };

  useEffect(() => {
    // 턴이 변경될 때마다 보드 상태를 갱신
    if (boardRef.current) {
      boardRef.current.turn = turn === "B" ? window.WGo.B : window.WGo.W;
      console.log(`WGo 보드 턴 업데이트: ${turn}`);
    }
  }, [turn]); // turn 상태가 변경될 때마다 실행
  
  return (
    <div>
      <h2>현재 턴: {turn === "B" ? "흑" : "백"}</h2>
      <div id="board" />
    </div>
  );
};

export default BadukBoard;
