import React, { useState, useEffect } from 'react';
import { db, auth } from '../firebase';
import { collection, addDoc, deleteDoc, doc, onSnapshot, getDoc } from 'firebase/firestore';
import { onAuthStateChanged } from 'firebase/auth';
import '../App.css'; // app.css 파일 임포트
import { query, orderBy } from 'firebase/firestore';

const Section2 = () => {
  const [post, setPost] = useState('');
  const [posts, setPosts] = useState([]);
  const [user, setUser] = useState(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [isStaff, setIsStaff] = useState(false);

  useEffect(() => {
    // 🔹 로그인한 사용자 정보 가져오기
    const unsubscribeAuth = onAuthStateChanged(auth, async (user) => {
      if (user) {
        setUser({
          uid: user.uid,
          email: user.email,
        });

        // 🔹 Firestore에서 해당 유저의 역할(admin/staff) 조회
        const userRef = doc(db, 'users', user.uid);
        const userSnap = await getDoc(userRef);
        
        if (userSnap.exists()) {
          const userData = userSnap.data();
          setIsAdmin(userData.admin === true);
          setIsStaff(userData.role === 'staff');
        }
      } else {
        setUser(null);
        setIsAdmin(false);
        setIsStaff(false);
      }
    });

    // 🔹 Firestore에서 게시글 가져오기
    const postsRef = query(collection(db, 'posts'), orderBy('timestamp', 'desc'));
    const unsubscribePosts = onSnapshot(postsRef, (snapshot) => {
      setPosts(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
    });

    return () => {
      unsubscribeAuth();
      unsubscribePosts();
    };
  }, []);

  // 🔹 게시글 추가 함수
  const handlePostSubmit = async () => {
    if (post.trim() && user) {
      await addDoc(collection(db, 'posts'), {
        content: post,
        timestamp: new Date(),
        authorId: user.uid, // 작성자 ID 저장
        authorEmail: user.email, // 작성자 이메일 저장 (관리 용도)
      });
      setPost('');
    }
  };

  // 🔹 게시글 삭제 함수 (본인 + 어드민/스태프만 가능)
  const handleDelete = async (postId, authorId) => {
    if (!user) return;

    const isAuthor = user.uid === authorId;

    if (isAuthor || isAdmin || isStaff) {
      await deleteDoc(doc(db, 'posts', postId));
    } else {
      alert("삭제할 권한이 없습니다.");
    }
  };

  return (
    <div>
      <h2>게시글</h2>

      {/* 게시글 입력 */}
      {user ? (
        <div>
          <textarea
            value={post}
            onChange={(e) => setPost(e.target.value)}
            placeholder="게시글을 입력하세요"
            rows="4"
            cols="50"
            className="textarea-post"
          />
          <button
            onClick={handlePostSubmit}
            className="button-submit"
          >
            게시글 올리기
          </button>
        </div>
      ) : (
        <p>로그인 후 게시글을 작성할 수 있습니다.</p>
      )}

      {/* 게시글 목록 */}
      <div>
        <h3>최근 게시글</h3>
        {posts.length > 0 ? (
          posts.map((post) => (
            <div key={post.id} className="post-container">
              <p>{post.content}</p>
              <p><small>{new Date(post.timestamp.seconds * 1000).toLocaleString()}</small></p>
              <p><small>작성자: {post.authorEmail}</small></p>

              {/* 삭제 버튼 (본인 + 어드민/스태프만 가능) */}
              {user && (user.uid === post.authorId || isAdmin || isStaff) && (
                <button
                  onClick={() => handleDelete(post.id, post.authorId)}
                  className="button-delete"
                >
                  삭제
                </button>
              )}
            </div>
          ))
        ) : (
          <p>게시글이 없습니다.</p>
        )}
      </div>
    </div>
  );
};

export default Section2;
